-- S5: 25 juicios Claude independientes; 23 PASS / 2 DEVOLVER (C12 y C21).
-- Solo AUTO publicadas, C04v2 PARCIAL; fuente original legada intacta. PG17 con ROLLBACK.
BEGIN;
DO $judgement$
DECLARE p jsonb; cd text; e record; h text; val jsonb; answer jsonb;
 n integer:=0; published integer:=0; returned integer:=0;
 leg_before jsonb; dep_before jsonb; 
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO leg_before FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO dep_before FROM lf_ops.nucleo_deprecaciones t;
 IF (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='VIGENTE')<>105 OR
    (SELECT count(*) FROM lf_ops.nucleo_reglas WHERE estado='CANDIDATA')<>37 OR
    (SELECT count(*) FROM lf_ops.reglas) NOT IN (215,586) OR
    (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0 OR
    ((SELECT count(*) FROM lf_ops.reglas)=586 AND
      (SELECT count(DISTINCT legacy_id) FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA')<>86)
 THEN RAISE EXCEPTION 'S5_JUDGEMENT_BASELINE_DRIFT'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"codigo":"S4-C04","version":2,"eval_id":456,"hash_paquete_atestado":"1e0409be1d7cbd7d7e9b0b56a64c00366dc9867cedabbf1fef3d1ee77cf9dc20","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":34},{"codigo":"S5-C01","version":1,"eval_id":457,"hash_paquete_atestado":"8ce27f0caf2afd57049d345a68aea96f1511ece2808117a39f13349961127efd","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":16,"familia":"SESSION"},{"codigo":"S5-C02","version":1,"eval_id":458,"hash_paquete_atestado":"7484b9eeb399ab74221a2af98ca185c42d3778dbc47d1fec8f56df0f667a60d3","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":17,"familia":"SESSION"},{"codigo":"S5-C03","version":1,"eval_id":459,"hash_paquete_atestado":"a441cc02244097ecbbbbfb7893e3ab522f9b78c5b0c79ecd1a45274ab904262e","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":