puntaje":1}},"legada_id":19,"familia":"SECURITY"},{"codigo":"S5-C14","version":1,"eval_id":470,"hash_paquete_atestado":"abfffd6f1480135362253c68d81866cc8097cb5ee1ad822544709bbfcd38ac93","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":25,"familia":"SECURITY"},{"codigo":"S5-C15","version":1,"eval_id":471,"hash_paquete_atestado":"edc7b3f310ab7ca738043e7a9e146c7c3a2d813360dd0a0ee953357b2138b162","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":30,"familia":"RATE_LIMIT"},{"codigo":"S5-C16","version":1,"eval_id":472,"hash_paquete_atestado":"969ec86096bce7951b038f0791d822e5616f3c288113cecf6dc73a18be37e095","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":125,"familia":"SECURITY"},{"codigo":"S5-C17","version":1,"eval_id":473,"hash_paquete_atestado":"92c741fe42178d19459cf7f63cae667bd86d5e816ecd4828b246f3b99982328d","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"El endpoint/webhook OTP tiene limitación backend independiente por session_id e IP, mientras C04 es validación OTP por IP entre sesiones."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":127,"familia":"SECURITY"},{"codigo":"S5-C18","version":1,"eval_id":474,"hash_paquete_atestado":"316c777a23e450d6b74ed3f206c1be786b6cff6c4e67e598c2c46270529751d0","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":317,"familia":"FINANCIAL_INTEGRITY_RECONCILIATION"},{"codigo":"S5-C19","version":1,"eval_id":475,"hash_paquete_atestado":"9c42806d4c0bc2978d390cfd59251c8ff333f629518d9741f29c1aacb377b5d4","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":0.9,"observacion":"El mensaje literal coincide con la fuente vigente REG_ATQ_008, ID 128, y no propone decisión adicional de negocio."}},"legada_id":128,"familia":"SECURITY"},{"codigo":"S5-C20","version":1,"eval_id":476,"hash_paquete_atestado":"a06bb782f00c10bc7f968ec3c302e1d928c529e6317bae5c5d859fdd9415aa01","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":130,"familia":"SECURITY"},{"codigo":"S5-C21","version":1,"eval_id":477,"hash_paquete_atestado":"6a363fb81bf3abf2572e6e9c09731fe8730642aab445a3c762804f94e86796f5","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.4,"observacion":"No existe variable verificada que represente cantidad inicial de planes, y la regla no nombra la cantidad exacta ni su fuente canónica."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":157,"familia":"OFFERS_INSTALLMENTS"},{"codigo":"S5-C22","version":1,"eval_id":478,"hash_paquete_atestado":"69cf28a7e582a344c2a9b97fbe1113511bd70426a85f97a63e9cf3240366212f","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.8,"observacion":"El copy funcional del modal y conservación de selección tiene texto denso; no editar esta versión ya evaluada, aclarar en revisión v2 si corresponde."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":238,"familia":"OFFERS_INSTALLMENTS"},{"codigo":"S5-C23","version":1,"eval_id":479,"hash_paquete_atestado":"61360e38099048395cb04cfe350fc566ca217290ec070e2f4719aa278abd7e49","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":425,"familia":"SECURITY"},{"codigo":"S5-C24","version":1,"eval_id":480,"hash_paquete_atestado":"ff7d4b2d5cfb664a458b8d0fafaa73093fdf8720b0c1f245a1ce1f1274ff770a","veredicto":"PASS","juez":"Claude independiente 2026-11-23 22:19 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":0.8,"observacion":"La condición de settlement backend es densa; simplificar redacción únicamente en nueva versión con nuevo hash y juicio."},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":533,"familia":"FINANCIAL_INTEGRITY_RECONCILIATION"}]'::jsonb) LOOP
   cd:=p->>'codigo';
   SELECT id,regla,version,hash_paquete INTO e
    FROM lf_ops.nucleo_evaluaciones
    WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
   IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR
      e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR
      (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR
      NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA')
   THEN RAISE EXCEPTION 'S5_ATTESTATION_DRIFT %',cd; END IF;
   h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
   IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S5_HASH_DRIFT %',cd; END IF;
   val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto',
    'puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE',
    'revisor_es_productor',false,'llamadas_modelo',1,
    'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s5_juicios_independientes_25_v1.json#'||cd);
   BEGIN
     PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
     RAISE EXCEPTION 'S5_NEGATIVE_HASH_ACCEPTED %',cd;
   EXCEPTION WHEN others THEN
     IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
   END;
   PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
   answer:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
   IF p->>'veredicto'='DEVOLVER' THEN
     IF answer->>'decision'='AUTO' THEN RAISE EXCEPTION 'S5_RETURN_AUTO %',cd; END IF;
     IF (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version)<>'CANDIDATA'
     THEN RAISE EXCEPTION 'S5_RETURN_STATE_CHANGED %',cd; END IF;
     returned:=returned+1;
   ELSIF answer->>'decision'='AUTO' THEN
     answer:=lf_ops.nucleo_regla_promover_v1(cd);
     IF answer->>'resultado'<>'PROMOVIDA_AUTO' OR
       (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version)<>'PUBLICADA'
     THEN RAISE EXCEPTION 'S5_PROMOTION_FAILED % %',cd,answer; END IF;
     published:=published+1;
   ELSE RAISE EXCEPTION 'S5_NOT_AUTO % %',cd,answer; END IF;
   n:=n+1;
 END LOOP;
 IF n<>25 OR published<>23 OR returned<>2
 OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE regla LIKE 'S5-C%' OR (regla='S4-C04' AND version=2))<>25
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM leg_before
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM dep_before
 THEN RAISE EXCEPTION 'S5_JUDGEMENT_READBACK_FAILED'; END IF;
 RAISE NOTICE 'S5_JUDGEMENTS_PASS 25 23_AUTO 2_DEVOLVER no_legacy_change';
END $judgement$;
DO $bridge$
DECLARE p jsonb; h text; cd text; lid integer; c integer:=0; replaced_before integer; replaced_after integer; leg_before jsonb;
BEGIN
 SELECT count(distinct legacy_id) INTO replaced_before FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO leg_before FROM lf_ops.reglas t;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"codigo":"S4-C04","legacy_id":34,"coverage":"PARCIAL","diff":"La tabla real lf_client.onboarding_sessions no tiene columna de estado ni enum; no hay equivalencia persistida unívoca de PASO1_COMPLETO, OTP_ENVIADO ni ABANDONADO. Guard de proyección no garantiza implementación de estados.","residual":"No existe mapeo unívoco persistido para PASO1_COMPLETO, OTP_ENVIADO y ABANDONADO; debe precisarse fuente canónica de eventos, transición y runtime."},{"codigo":"S5-C01","legacy_id":16,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Limitar concurrencia de onboarding por cuenta, no IP con condición de violación y fuente original 16.","residual":""},{"codigo":"S5-C02","legacy_id":17,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Reanudar sesión activa conservando perfil pero reiniciando OTP con condición de violación y fuente original 17.","residual":""},{"codigo":"S5-C03","legacy_id":26,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Bloquear exceso de registros por IP según parámetros reales con condición de violación y fuente original 26.","residual":""},{"codigo":"S5-C04","legacy_id":27,"coverage":"REEMPLAZADA","diff":"El límite de validaciones OTP por IP entre sesiones usa AUTH/OTP_VALIDATION_PER_IP_*; el webhook separado S5-C17 aplica políticas propias por session_id e IP.","residual":""},{"codigo":"S5-C05","legacy_id":28,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Limitar envíos OTP acumulados por celular entre sesiones con condición de violación y fuente original 28.","residual":""},{"codigo":"S5-C06","legacy_id":29,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Limitar inicios de onboarding por DNI y ventana configurada con condición de violación y fuente original 29.","residual":""},{"codigo":"S5-C07","legacy_id":399,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Aplicar avisos y cierre por inactividad según política de sesión B2B con condición de violación y fuente original 399.","residual":""},{"codigo":"S5-C08","legacy_id":400,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Resguardar rotación, refresh y concurrencia de sesión B2B con condición de violación y fuente original 400.","residual":""},{"codigo":"S5-C09","legacy_id":512,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Autenticar cuenta existente solo con OTP del celular vinculado con condición de violación y fuente original 512.","residual":""},{"codigo":"S5-C10","legacy_id":513,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Conceder acceso solo tras rebinding atómico y revocación previa con condición de violación y fuente original 513.","residual":""},{"codigo":"S5-C11","legacy_id":515,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Crear sesión autenticada únicamente tras alta completa con condición de violación y fuente original 515.","residual":""},{"codigo":"S5-C13","legacy_id":19,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Invalidar OTP agotado y respetar cooldown sin bloqueo permanente con condición de violación y fuente original 19.","residual":""},{"codigo":"S5-C14","legacy_id":25,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Validar formato de todos los campos antes de consultar base con condición de violación y fuente original 25.","residual":""},{"codigo":"S5-C15","legacy_id":30,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Mantener timer ordinario visible con precedencia del cooldown OTP con condición de violación y fuente original 30.","residual":""},{"codigo":"S5-C16","legacy_id":125,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Firmar y verificar webhook OTP con HMAC y timestamp con condición de violación y fuente original 125.","residual":""},{"codigo":"S5-C17","legacy_id":127,"coverage":"REEMPLAZADA","diff":"Endpoint/webhook OTP con cuota independiente por session_id e IP vía politicas_rate_limit; no sustituye validaciones por IP entre sesiones gobernadas en S5-C04.","residual":""},{"codigo":"S5-C18","legacy_id":317,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Conservar referencia canónica de pago en notificaciones y overlays con condición de violación y fuente original 317.","residual":""},{"codigo":"S5-C19","legacy_id":128,"coverage":"REEMPLAZADA","diff":"Copia literalmente el mensaje vigente de REG_ATQ_008: No pudimos procesar tu solicitud. Intenta nuevamente o contáctanos.","residual":""},{"codigo":"S5-C20","legacy_id":130,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Evitar filtraciones temporales por validación DNI, celular y OTP con condición de violación y fuente original 130.","residual":""},{"codigo":"S5-C22","legacy_id":238,"coverage":"REEMPLAZADA","diff":"Cubre apertura sin navegación y conservación de selección en modal; distinto de regla anterior centrada en el cierre.","residual":""},{"codigo":"S5-C23","legacy_id":425,"coverage":"REEMPLAZADA","diff":"Especialización de obligación de Normalizar errores de credenciales B2B sin revelar existencia con condición de violación y fuente original 425.","residual":""},{"codigo":"S5-C24","legacy_id":533,"coverage":"REEMPLAZADA","diff":"Establece liquidación solo con prueba ledger, obligaciones contractuales y confirmación de aliado, no con avance del cronograma.","residual":""}]'::jsonb) LOOP
   lid:=(p->>'legacy_id')::int; cd:=p->>'codigo';
   IF NOT EXISTS (SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
      IF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S5_SOURCE_MISSING %',lid; END IF;
      RAISE NOTICE 'S5_PG17_FIXTURE_LEGACY_NOT_INCLUDED %',lid; CONTINUE;
   END IF;
   IF NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND estado='PUBLICADA') THEN
      RAISE EXCEPTION 'S5_UNPUBLISHED_BRIDGE %',cd; END IF;
   h:=lf_ops.nucleo_hash_paquete_v1(cd,(SELECT max(version) FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND estado='PUBLICADA'));
   INSERT INTO lf_ops.lf_nucleo_cobertura_legada
    (legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
   VALUES(lid,cd,(SELECT max(version) FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND estado='PUBLICADA'),
      p->>'coverage',p->>'diff',
      jsonb_build_object('fuente','lf_ops.reglas/'||lid,
       'contraste','LEGADA: '||coalesce((SELECT descripcion FROM lf_ops.reglas WHERE id=lid),'(sin descripción)')||
       ' NUCLEO: '||coalesce((SELECT descripcion FROM lf_ops.nucleo_regla_versiones WHERE regla=cd ORDER BY version DESC LIMIT 1),'(sin texto)')||
       ' DIFERENCIA: '||coalesce(p->>'diff','-'),
       'residual',p->>'residual','juicio','Claude independiente S5 2026-11-23 22:19',
       'limite_aceptacion','Cobertura por obligación textual; binding físico requiere QA separado'),
      h,'GPT-6 / Claude S5 independiente');
   c:=c+1;
 END LOOP;
 SELECT count(distinct legacy_id) INTO replaced_after FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (c<>23 OR replaced_after<>replaced_before+22)
 THEN RAISE EXCEPTION 'S5_BRIDGE_COUNT_DRIFT links=% previous=% replaced=%',c,replaced_before,replaced_after; END IF;
 IF (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM leg_before
 OR (SELECT count(*) FROM lf_ops.nucleo_deprecaciones)<>0
 THEN RAISE EXCEPTION 'S5_LEGACY_TOUCHED'; END IF;
 RAISE NOTICE 'S5_BRIDGE_PASS links=% new_replaced=%',c,replaced_after-replaced_before;
END $bridge$;
COMMIT;